    /// If the resulting codepoint is zero (a NULL terminator), or <c>*pslen</c> is zero, it will not advance
    /// <c>*pstr</c> or <c>*pslen</c> at all.
    /// </para>
    /// <para>
    /// Generally this function is called in a loop until it returns zero, adjusting its parameters each iteration.
    /// </para>
    /// <para>
    /// If an invalid UTF-8 sequence is encountered, this function returns SDL_INVALID_UNICODE_CODEPOINT and advances
    /// the string/length by one byte (which is to say, a multibyte sequence might produce several
    /// SDL_INVALID_UNICODE_CODEPOINT returns before it syncs to the next valid UTF-8 sequence).
    /// </para>
    /// <para>
    /// Several things can generate invalid UTF-8 sequences, including overlong encodings, the use of UTF-16 surrogate
    /// values, and truncated data. Please refer to [RFC3629](https://www.ietf.org/rfc/rfc3629.txt) for details.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="pstr">a pointer to a UTF-8 string pointer to be read and adjusted.</param>
    /// <param name="pslen">
    /// a pointer to the number of bytes in the string, to be read and adjusted. NULL is allowed.
    /// </param>
    /// <returns>the first Unicode codepoint in the string.</returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_StepUTF8")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial uint StepUTF8(byte** pstr, nuint* pslen);

