    /// <param name="inbytesleft">The number of bytes in the input buffer.</param>
    /// <param name="outbuf">Address of variable that points to the output buffer.</param>
    /// <param name="outbytesleft">The number of bytes in the output buffer.</param>
    /// <returns>the number of conversions on success, or a negative error code.</returns>
